import { MeshStandardNodeMaterial, Mesh } from 'three/webgpu';
import { uniform, vec3, mix, uv, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, PlaneGeometry, CircleGeometry,
    MeshBasicMaterial, Color, DoubleSide,
    AmbientLight, PointLight
  } = ctx.THREE;

  const group = new Group();
  group.name = 'ornamental-divider';

  const colorSrc = config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colorSrc.ink ?? '#16161d');
  const paper = new Color(colorSrc.paper ?? '#e8ecf2');
  const accent = new Color(colorSrc.accent ?? '#ff2a38');
  const surface = new Color(colorSrc.surface ?? '#0b0b10');

  const timelines = [];
  const disposables = [];

  // --- Backdrop gradient strip (machined surface) ---------------------------------------
  const backdropMat = new MeshStandardNodeMaterial();
  const bgGradient = mix(
    vec3(surface).add(vec3(0.02, 0.02, 0.03)),
    vec3(ink),
    smoothstep(float(0.0), float(1.0), uv().y)
  );
  backdropMat.colorNode = bgGradient;
  backdropMat.roughness = 0.62;
  backdropMat.metalness = 0.35;
  backdropMat.side = DoubleSide;
  const backdrop = new Mesh(new PlaneGeometry(3.2, 0.9), backdropMat);
  backdrop.position.set(0, 0, -0.35);
  group.add(backdrop);
  disposables.push(backdropMat, backdrop.geometry);

  // --- Machined rule (the GLB asset) -----------------------------------------------------
  const ruleGroup = new Group();
  ruleGroup.position.set(0, 0, 0);
  group.add(ruleGroup);

  const meshUrl = config.meshUrl ?? config.intent?.visualSpec?.meshUrl;
  let heroRoot = null;

  // Accent edge-light to read the jewel red
  const rim = new PointLight(accent.getHex(), 0.55, 4.0, 2.0);
  rim.position.set(0.9, 0.15, 0.8);
  group.add(rim);

  const fill = new PointLight(paper.getHex(), 0.35, 3.0, 2.0);
  fill.position.set(-0.9, -0.1, 0.9);
  group.add(fill);

  const amb = new AmbientLight(ink.getHex(), 0.5);
  group.add(amb);

  // Contact shadow disc under the rule to ground the jewel
  const shadowMat = new MeshBasicMaterial({
    color: 0x000000, transparent: true, opacity: 0.45, depthWrite: false
  });
  const shadow = new Mesh(new CircleGeometry(0.18, 32), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.08, 0.001);
  group.add(shadow);
  disposables.push(shadowMat, shadow.geometry);

  let restingY = 0;
  let liftTween = null;

  // Kick GLB load (cached); populate synchronously-returned group when ready
  if (meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      const root = gltf.scene ?? gltf;
      heroRoot = root;
      // Ensure PBR materials honour the atelier palette accent on any "jewel" parts
      root.traverse?.((obj) => {
        if (obj.isMesh) {
          obj.material?.dispose?.();
          const m = new MeshStandardNodeMaterial();
          // Default machined-metal look
          m.roughness = 0.55;
          m.metalness = 0.5;
          m.colorNode = mix(vec3(paper).mul(0.6), vec3(ink), 0.3);
          // Accent jewel: a small emissive ruby core at center, achieved via extra mesh swap
          obj.material = m;
          obj.castShadow = true;
          obj.receiveShadow = true;
        }
      });
      root.scale.set(1, 1, 1);
      ruleGroup.add(root);

      // Entrance: weighted-settle
      ruleGroup.scale.set(0.92, 0.92, 0.92);
      ruleGroup.position.y = -0.05;
      const tl = gsap.timeline({ defaults: { ease: 'power4.out' } });
      tl.to(ruleGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9 }, 0)
        .to(ruleGroup.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0)
        .to(backdrop.material, { opacity: 1, duration: 0.6 }, 0);
      timelines.push(tl);
    }).catch(() => { /* graceful: rule empty, jewel disc still present */ });
  }

  // --- Center jewel accent (procedural, ensures the "jewel" reads even pre-load) --------
  const jewelMat = new MeshStandardNodeMaterial();
  jewelMat.colorNode = vec3(accent);
  jewelMat.emissiveNode = vec3(accent).mul(0.9);
  jewelMat.roughness = 0.25;
  jewelMat.metalness = 0.15;
  const jewel = new Mesh(new CircleGeometry(0.05, 24), jewelMat);
  jewel.position.set(0, 0, 0.02);
  group.add(jewel);
  disposables.push(jewelMat, jewel.geometry);

  // Subtle idle breathing on the jewel
  const breathe = gsap.to(jewel.position, {
    z: 0.04, duration: 2.4, yoyo: true, repeat: -1, ease: 'sine.inOut'
  });
  timelines.push(breathe);

  // --- Interaction handlers -------------------------------------------------------------
  group.userData.handlers = {
    onPointerOver: () => {
      if (liftTween) liftTween.kill();
      liftTween = gsap.to(group.position, {
        y: 0.15, duration: 0.5, ease: 'power3.out',
        onStart: () => { restingY = group.position.y; }
      });
      timelines.push(liftTween);
    },
    onPointerOut: () => {
      if (liftTween) liftTween.kill();
      liftTween = gsap.to(group.position, {
        y: restingY, duration: 0.45, ease: 'power3.out'
      });
      timelines.push(liftTween);
    },
    onClick: () => {
      const press = gsap.timeline();
      press.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out' })
           .to(group.scale, { x: 1, y: 1, duration: 0.3, ease: 'power4.out' });
      timelines.push(press);
      ctx.emit('hub-home.select', { node: 'ornamental-divider' });
    }
  };

  // --- Cleanup --------------------------------------------------------------------------
  group.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill?.(); } catch (_) {} });
    timelines.length = 0;
    disposables.forEach((d) => {
      try { d?.dispose?.(); } catch (_) {}
    });
    disposables.length = 0;
    heroRoot?.traverse?.((o) => {
      try { o?.geometry?.dispose?.(); } catch (_) {}
      try { o?.material?.dispose?.(); } catch (_) {}
    });
  };

  return group;
}
